from __future__ import absolute_import
from .configuration_management.commissioning_wizard.commissioning_wizard import CommissioningWizardPage
from .configuration_management.parameter_editor import ParameterEditorPage
from .configuration_management.definition_errors import DefinitionErrorsPage
from .configuration_management.relation_errors import RelationErrorsPage
from .configuration_management.hardware_errors import HardwareErrorsPage
from .certificate_management import (BtsCertificatesPage, AutomaticManagementPage,
                                     CertificateRevocationListsPage, VendorCertificatesPage)
from .configuration_reset import ConfigurationResetPage
from .centralized_ret_management import CentralizedRaeManagementPage
from .ncf_configuration import NcfParameterEditorPage, NcfDefinitionErrorsPage, NcfRelationErrorsPage


class Configuration(object):
    """
    The class corresponding to Configuration page on selenium_coam web, all operations under Configuration
    page will be implemented or added in its corresponding classes.
    """

    def __init__(self, driver, download_checker):
        self._commissioning_wizard = CommissioningWizardPage(driver)
        self._parameter_editor = ParameterEditorPage(driver, download_checker)
        self._definition_errors = DefinitionErrorsPage(driver)
        self._relation_errors = RelationErrorsPage(driver)
        self._hardware_errors = HardwareErrorsPage(driver)
        self._bts_certificates = BtsCertificatesPage(driver)
        self._automatic_management = AutomaticManagementPage(driver)
        self._certificate_revocation_lists = CertificateRevocationListsPage(driver)
        self._vendor_certificates = VendorCertificatesPage(driver)
        self._configuration_reset = ConfigurationResetPage(driver)
        self._centralized_rae_management = CentralizedRaeManagementPage(driver, download_checker)
        self._ncf_parameter_editor = NcfParameterEditorPage(driver, download_checker)
        self._ncf_definitions_errors = NcfDefinitionErrorsPage(driver)
        self._ncf_relation_errors = NcfRelationErrorsPage(driver)

    @property
    def commissioning_wizard(self):
        return self._commissioning_wizard

    @property
    def parameter_editor(self):
        return self._parameter_editor

    @property
    def definition_errors(self):
        return self._definition_errors

    @property
    def relation_errors(self):
        return self._relation_errors

    @property
    def hardware_errors(self):
        return self._hardware_errors

    @property
    def bts_certificates(self):
        return self._bts_certificates

    @property
    def automatic_management(self):
        return self._automatic_management

    @property
    def certificate_revocation_lists(self):
        return self._certificate_revocation_lists

    @property
    def vendor_certificates(self):
        return self._vendor_certificates

    @property
    def configuration_reset(self):
        return self._configuration_reset

    @property
    def centralized_rae_management(self):
        return self._centralized_rae_management

    @property
    def ncf_parameter_editor(self):
        return self._ncf_parameter_editor

    @property
    def ncf_definitions_errors(self):
        return self._ncf_definitions_errors

    @property
    def ncf_relation_errors(self):
        return self._ncf_relation_errors
